mapper.update:
update product
name = #{name}, description = #{description}, price = #{price}, stock = #{stock}, image = #{image}, category_id = #{categoryId}, update_time = now()
where id = #{id}

mapper.select:
select count(*) from product 

    and name like concat('%',#{name},'%')
    and status = #{status}
    and category_id = #{categoryId}

select * from product
where status = 1 and category_id = #{categoryId}
order by id asc

select p.*,c.name as categoryName from product p left join category c on p.category_id = c.id

    and p.name like concat('%',#{productPageQueryDTO.name},'%')
    and p.status = #{productPageQueryDTO.status}
    and p.category_id = #{productPageQueryDTO.categoryId}

order by p.id asc limit #{begin},#{productPageQueryDTO.pageSize}

select id,category_id,name,description,price,sales,image,status from product

    id > #{lastId}

order by id asc
limit #{batchSize}
